const app=document.querySelector('#app');let timer=null;let position=0;
function terrain(units=true){return `<svg viewBox="0 0 600 440" role="img" aria-label="Illustrative tactical terrain map"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="currentColor" opacity=".10"/></pattern></defs><rect width="600" height="440" fill="url(#grid)"/><g fill="none" stroke="currentColor" opacity=".18">${Array.from({length:8},(_,i)=>`<path d="M${-120+i*24} 440 Q${70+i*25} 300 ${10+i*28} 170 T${280+i*25} -40"/>`).join('')}<path d="M0 320Q180 240 230 290T600 200" stroke-width="25" opacity=".35"/><path d="M0 320Q180 240 230 290T600 200" stroke-width="2"/></g><g fill="currentColor" opacity=".13"><rect x="345" y="130" width="32" height="45" transform="rotate(20 345 130)"/><rect x="395" y="156" width="45" height="24"/><rect x="370" y="205" width="28" height="20"/></g><g id="routeLayer"><path d="M100 355L210 305L290 230L410 150" stroke="var(--accent)" stroke-width="2" stroke-dasharray="7 7" fill="none"/><circle cx="410" cy="150" r="40" fill="none" stroke="var(--accent)"/><path d="M410 135v30m-15-15h30" stroke="var(--accent)"/></g>${units?'<g id="unitLayer"><g id="squad" transform="translate(210 305)"><circle r="20" fill="var(--accent)" opacity=".15"/><circle r="6" fill="var(--accent)"/><text x="17" y="-13" font-size="11" fill="var(--ink)" font-family="monospace">ALPHA</text></g><g transform="translate(270 330)"><path d="M0-6L7 6H-7Z" fill="var(--accent)"/><text x="14" y="5" font-size="10" fill="var(--ink)" font-family="monospace">BRAVO</text></g></g>':''}</svg>`}
function link(page,text,cls=''){return `<a class="${cls}" href="#${page}">${text}</a>`}

function navigation(page){
 const links=[['home','Community'],['media','Media'],['operations','Sessions']];
 return `<nav aria-label="Main navigation">${links.map(([route,label])=>`<a href="#${route}" ${page===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
}
function shell(page,content){
 return `<div class="field-shell"><header class="quiet-header">${link('home','Global Conflicts','quiet-brand')}<button class="menu-trigger" id="openMenu" popovertarget="siteMenu" aria-expanded="false" aria-controls="siteMenu">Explore pages <span aria-hidden="true">☰</span></button></header><div id="siteMenu" class="field-menu" popover="auto"><div class="menu-top"><span>Global Conflicts</span><button id="closeMenu" aria-label="Close menu">Close ×</button></div>${navigation(page)}${link('playback','Playback','menu-extra')}<a class="menu-discord" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a></div><main>${content}</main><footer><span>Global Conflicts</span><a href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Discord ↗</a></footer></div>`;
}
let youtubeApiPromise;
let youtubePlayers=[];
function loadYouTubeApi(){
 if(window.YT?.Player)return Promise.resolve(window.YT);
 if(!youtubeApiPromise)youtubeApiPromise=new Promise((resolve,reject)=>{
  window.onYouTubeIframeAPIReady=()=>resolve(window.YT);
  const script=document.createElement('script');
  script.src='https://www.youtube.com/iframe_api';script.async=true;
  script.onerror=()=>{youtubeApiPromise=null;script.remove();reject(new Error('YouTube API unavailable'))};
  document.head.append(script);
 });
 return youtubeApiPromise;
}
function setVideoStartingVolume(iframe,playOnReady=false){
 loadYouTubeApi().then(YT=>{
  if(!iframe?.isConnected)return;
  const player=new YT.Player(iframe,{events:{onReady:event=>{
   if(!iframe.isConnected)return;
   event.target.setVolume(25);
   if(playOnReady)event.target.playVideo();
  }}});
  youtubePlayers.push(player);
 }).catch(()=>{/* The native player and Watch on YouTube link remain usable. */});
}
function render(){
 youtubePlayers.forEach(player=>player.destroy());youtubePlayers=[];
 window.scrollTo(0,0);clearInterval(timer);timer=null;
 const parts=location.hash.slice(1).split('/').filter(Boolean);
 const requested=parts.length>1?parts[parts.length-1]:parts[0];
 const pages=['home','operations','playback','join','media'];
 const page=pages.includes(requested)?requested:'home';
 if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);
 document.body.className='field page-'+page;
 app.innerHTML=shell(page,page==='home'?home():page==='media'?media():page==='playback'?playback():page==='operations'?operations():join());
 wireNavigation();if(page==='playback')wirePlayer();
 if(page==='media')setVideoStartingVolume(document.querySelector('.media-feature iframe'));
 document.title=page==='home'?'Global Conflicts — One-life Arma Reforger':({media:'Media',operations:'Sessions',playback:'Playback',join:'Join us'}[page]+' — Global Conflicts');
}
function home(){
 return `<section class="field-opening"><div class="opening-copy"><h1>One life.<br><span>Arma Reforger.</span></h1><p>An international Arma community with 15+ years of tactical teamwork and good times—no ranks, no attendance requirements, just join and play when you can.</p><p class="opening-time">Saturday & Sunday · 19:00 UTC</p><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a></div><figure class="opening-media"><img src="squad.jpg" alt="Two soldiers advancing together beside a building, from the Global Conflicts community archive" fetchpriority="high"></figure><button class="scroll-invitation" id="exploreBelow">See how we play <span aria-hidden="true">↓</span></button></section><section id="howWePlay" class="field-story"><div class="story-video" id="introPlayer"><button id="playIntro" aria-label="Play the Global Conflicts introduction"><img src="intro-thumbnail.jpg" alt="Global Conflicts guide to joining and playing Arma Reforger"><span class="story-play" aria-hidden="true">▶</span></button><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></section><section class="field-join-section"><div><h2>Your next<br>session starts here.</h2><p class="large-session-time">Saturday & Sunday<br><span>19:00 UTC</span></p></div><div class="join-copy"><p>Discord is where we meet, plan, and play. Get your server details and mods, ask questions, and find your squad.</p><p>Bring a working microphone and a mature attitude. We’ll help you get started.</p><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener"><img class="discord-icon" src="discord.svg" alt="" width="20" height="20">Join us on Discord ↗</a></div></section><section class="field-more"><img src="community.jpg" alt="A scene from the Global Conflicts community archive"><div><h2>There’s more to explore.</h2><p>Community videos, photos, and stories from past operations.</p>${link('media','Explore our media →','text-link')}</div></section>`;
}
function wireNavigation(){
 const panel=document.querySelector('#siteMenu'),trigger=document.querySelector('#openMenu');
 let openTimer,closeTimer,pinned=false;
 const isOpen=()=>panel.matches(':popover-open');
 const closeMenu=()=>{clearTimeout(openTimer);clearTimeout(closeTimer);pinned=false;if(isOpen())panel.hidePopover()};
 const showMenu=()=>{if(!isOpen())panel.showPopover()};
 const canHover=()=>window.matchMedia('(hover: hover) and (pointer: fine)').matches;
 const scheduleClose=()=>{clearTimeout(openTimer);if(!pinned)closeTimer=setTimeout(closeMenu,280)};
 trigger.onclick=event=>{event.preventDefault();clearTimeout(openTimer);clearTimeout(closeTimer);if(isOpen()&&pinned){closeMenu()}else{pinned=true;showMenu()}};
 trigger.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'&&canHover()){clearTimeout(closeTimer);openTimer=setTimeout(showMenu,160)}});
 trigger.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'&&canHover())scheduleClose()});
 panel.addEventListener('pointerenter',()=>clearTimeout(closeTimer));
 panel.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'&&canHover())scheduleClose()});
 panel.addEventListener('focusin',()=>{pinned=true;clearTimeout(closeTimer)});
 panel.addEventListener('toggle',()=>{trigger.setAttribute('aria-expanded',String(isOpen()));if(!isOpen()){pinned=false;clearTimeout(openTimer);clearTimeout(closeTimer)}});
 document.querySelector('#closeMenu').onclick=()=>{closeMenu();trigger.focus()};
 panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();if(a.getAttribute('href')===location.hash)window.scrollTo(0,0)}));
 document.querySelector('#exploreBelow')?.addEventListener('click',()=>document.querySelector('#howWePlay').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 document.querySelector('#playIntro')?.addEventListener('click',()=>{document.querySelector('#introPlayer').innerHTML='<div class="video-embed"><iframe src="https://www.youtube-nocookie.com/embed/_SW1tEkcfRU?enablejsapi=1&amp;autoplay=0" title="Global Conflicts Guide: How to Join and Play Arma Reforger With Us" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a>';setVideoStartingVolume(document.querySelector('#introPlayer iframe'),true)})
}
function operations(){const rows=['Saturday','Sunday'].map((day,i)=>`<article><span class="session-number">0${i+1}</span><div><span class="eyebrow">Weekly sessions</span><h2>${day}</h2></div><div class="session-time">19:00 <span>UTC</span></div>${link('join','Joining instructions ↗','text-link')}</article>`).join('');return `<div class="page-heading"><span class="eyebrow">Deployment schedule</span><h1>Weekend sessions.</h1><p>One-life Arma Reforger milsim, every Saturday and Sunday at 19:00 UTC. Join Discord for setup and session updates.</p></div><section class="schedule">${rows}</section><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join Discord for session details ↗</a>`}
function join(){return `<section class="page-heading join-focused"><span class="eyebrow">YOUR FIRST SESSION</span><h1>Join the squad.</h1><p>A working microphone. A mature attitude. One shared objective.</p><ol class="joining-steps"><li>Join Discord and meet the community.</li><li>Get the Reforger server details and required mods.</li><li>Be ready Saturday or Sunday at 19:00 UTC.</li></ol><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a><p>${link('media','Watch the joining guide →','text-link')}</p></section>`}
function media(){return `<section class="media-page"><div class="media-heading"><span class="eyebrow">GET TO KNOW GLOBAL CONFLICTS</span><h1>See how we play.</h1><p>One-life Arma Reforger milsim, from your first connection to the mission briefing.</p></div><div class="media-feature"><div class="video-embed"><iframe src="https://www.youtube-nocookie.com/embed/_SW1tEkcfRU?enablejsapi=1" title="Global Conflicts Guide: How to Join and Play Arma Reforger With Us" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="media-feature-caption"><h2>How to join & play</h2><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></div><div class="media-explore"><article class="media-archive"><img src="community.jpg" alt="Vehicles on a forest road from the Global Conflicts community archive"><div><span class="eyebrow">FROM THE COMMUNITY ARCHIVE</span><h2>More from the field.</h2><a href="https://www.youtube.com/@GlobalConflicts_" target="_blank" rel="noopener" class="text-link">Explore the GC video channel ↗</a></div></article><section class="media-links"><div><h2>Next session</h2><p>Saturday & Sunday · 19:00 UTC</p>${link('operations','Session details →','text-link')}</div><div><h2>Past operations & community</h2><p>Photos, event updates, and after-action discussions live on Discord.</p><a href="https://discord.globalconflicts.net" target="_blank" rel="noopener" class="text-link">Explore our Discord ↗</a></div><div><h2>Playback lab</h2><p>Try a simulated briefing with chapters and a tactical timeline.</p>${link('playback','Open the playback demo →','text-link')}</div></section></div></section>`}
function playback(){return `<div class="page-heading player-heading"><div><span class="eyebrow">After action / briefing room · SIMULATED DATA</span><h1>Operation Pine</h1></div><p>Fictional scenario · 2 min demo</p></div><section class="workspace" aria-label="Briefing player"><aside class="sidebar"><div class="eyebrow">Chapters</div><button data-time="0">01 &nbsp; Situation</button><button data-time="35">02 &nbsp; Approach</button><button data-time="70">03 &nbsp; Objective</button><button data-time="100">04 &nbsp; Debrief</button></aside><div class="map">${terrain()}<span class="map-caption">ILLUSTRATIVE TERRAIN / NOT GAME DATA</span></div><aside class="intel"><div><span class="eyebrow">Briefing notes</span><h3 id="chapterTitle">Situation</h3><p id="chapterNote"></p></div><div><span class="eyebrow">Map layers</span><label><input type="checkbox" checked id="units"> Squad positions</label><label><input type="checkbox" checked id="routes"> Planned route</label></div></aside></section><div class="timeline"><button id="play" aria-label="Play simulated briefing">▶ Play</button><output id="time">00:00 / 02:00</output><input aria-label="Playback position" id="scrub" type="range" min="0" max="120" value="0"><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value="2">2× speed</option><option value="4">4× speed</option></select><button id="reset">↺ Reset</button></div><p class="demo-note">Interactive concept with simulated data. Live recordings and game integration are future work.</p>`}
function wirePlayer(){position=0;const notes=['Alpha and Bravo assemble southwest of the objective. Review the planned approach.','Alpha advances along the marked route. Bravo holds the southern approach.','Alpha reaches the objective area. Coordinate the final approach with Bravo.','Review squad movement and timing. Use the timeline to revisit key moments.'];function update(){document.querySelector('#scrub').value=position;document.querySelector('#time').textContent=`${String(Math.floor(position/60)).padStart(2,'0')}:${String(Math.floor(position%60)).padStart(2,'0')} / 02:00`;let idx=position<35?0:position<70?1:position<100?2:3;document.querySelector('#chapterTitle').textContent=['Situation','Approach','Objective','Debrief'][idx];document.querySelector('#chapterNote').textContent=notes[idx];document.querySelectorAll('[data-time]').forEach((b,i)=>b.classList.toggle('selected',i===idx));document.querySelector('#squad').setAttribute('transform',`translate(${100+position*2.58} ${355-position*1.7})`)}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='▶ Play';document.querySelector('#play').setAttribute('aria-label','Play simulated briefing')}document.querySelector('#play').onclick=()=>{if(timer){stop();return}if(position>=120)position=0;document.querySelector('#play').textContent='Ⅱ Pause';document.querySelector('#play').setAttribute('aria-label','Pause simulated briefing');timer=setInterval(()=>{position=Math.min(120,position+.25*Number(document.querySelector('#speed').value));update();if(position>=120)stop()},250)};document.querySelector('#scrub').oninput=e=>{position=Number(e.target.value);update()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{position=Number(b.dataset.time);update()});document.querySelector('#reset').onclick=()=>{stop();position=0;update()};document.querySelector('#units').onchange=e=>document.querySelector('#unitLayer').style.display=e.target.checked?'':'none';document.querySelector('#routes').onchange=e=>document.querySelector('#routeLayer').style.display=e.target.checked?'':'none';update()}
window.addEventListener('hashchange',render);render();

